const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['協會解散了要把印信繳回嗎','繳回立案證書、圖記'],['解散要不要繳立案證書','繳回立案證書、圖記'],['社團關掉圖記要還嗎','繳回立案證書、圖記'],
['解散登記要多久內辦','解散報告的期限請洽承辦'],['協會解散要幾天內報縣府','解散報告的期限請洽承辦'],
['會員都走光了協會會自動解散嗎','不會，仍要依規定辦解散'],['會員剩不到幾個人協會就算解散嗎','不會，仍要依規定辦解散'],['成員都退會協會會不會自動解散','不會，仍要依規定辦解散'],
['解散的決議要寫在會議紀錄嗎','大會紀錄要報縣府備查'],['協會解散要不要有會議紀錄','大會紀錄要報縣府備查'],
['社團解散財產捐給別的協會可以嗎','要看章程怎麼寫'],['解散後剩餘財產可以轉給其他團體嗎','要看章程怎麼寫'],['協會結束剩下的錢能捐給別的社團嗎','要看章程怎麼寫'],
];
const no=['解散要幾分之幾同意','協會想解散要怎麼辦','解散要開會員大會嗎','協會解散要報給誰','剩餘財產可以分給會員嗎','清算人是誰','清算要多久','解散後帳簿要保存多久','理事長交接要交印信嗎','證書遺失怎麼辦','印信遺失怎麼辦','理事長跑掉了怎麼解散','協會欠錢怎麼解散','合作社解散要繳回證書嗎','社區發展協會解散要多久內報','會議紀錄要保存多久','會議紀錄怎麼寫','協會合併要開會嗎','公會解散財產捐給別的團體可以嗎','會員退會人數不夠怎麼辦','捐款能抵稅嗎'];
const pat=/繳回立案證書、圖記|解散報告的期限請洽承辦|不會，仍要依規定辦解散|大會紀錄要報縣府備查|要看章程怎麼寫/;
let bad=0;
for(const [q,k] of yes){const x=A(q);if(!x||!x.direct||!(x.summary+x.title).includes(k)){console.error('FAIL',q,x&&x.title);bad++;}}
for(const q of no){const x=A(q);if(x&&typeof x==='object'&&pat.test(x.title)){console.error('OVERTRIGGER',q,x.title);bad++;}}
if(bad)throw new Error('patrol64 failed '+bad);console.log('ok');
